INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p258864-mgt440', 'stk-foxxx', 'MGT 440', 'info', '{"desc": "بسم الله الرحمن الرحيم\nالسلام عليكم يا شباب اشوفكم ضايعين وما أحد رد عليكم\n\nالمهم انا خريج ادارة اعمال من دفعة 22 , اخذيت المادة مع الدكتور القاظي تقريبا قبل سنة .\n\nالي اقدر افيدكم في ان الدكتور علي درجة كبيرة من الاحترام و يحمل معلومات كبيرة يكون من المستحيل ان\nتخلص الكورس معا بدون ما تستفيد فايدة كبيرة\n\nالدكتور هو دكتور بارت تايم في الجامعة - متقاعد من سابك - يحمل معلومات واقعية ومتجددة عن وضع السوق وتحركاتة\n\nمحاظرتة لا تفوت وليس فيها اي نوع من الملل .\nمن ناحية الاختبارات فيها صعوبة - يعني لازم تذاكر - يعني الي يبي جريد وهو جالس لا يدخل عندة\nعندة تقريبا 5-7 كوزات علي طول السمستر يختبرك بشكل مفاجئ - يعني لازم تكون مستعد علي طول\n\nبس اذا تذاكر اول بأول وتركز معا راح تاخذ جريد وتستفيد كثير.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mgt-440/54852/8", "user": "Foxxx", "ts": 1207638540000, "tid": 54852, "pn": 8}}', 1207638540000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hisham.s-mgt440', 'stk-hisham.s', 'MGT 440', 'doc', '{"docs": [{"id": "stk-dr-f98468", "n": "Dr. Muhammad Jameel Qazi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "مساء الخير\n\nترم 142\n\nالمادة : MGT440 &450 بنفس الترم\n\nMGT440\n\nادارة الاعمال الدولية\nالكورس ممتع جدا ، خصوصا اذا كنت مطلع ومهتم بهالموضوع ، مالك الا تجيب قهوتك وتتفرغ للنقاش والاستماع .\n\nو يتطرق للعديد من الموضعات التي تخص التجارة الدولية من انواع الشركات وتصنيفها والصادرات والواردات والصناعة واثارها على الاقتصاد ومختلف الامور التي تعنى ببيئة العمل الدولية .\n\nMGT450\nادارة التغيير والابتكار\nيتطرق الكورس لانواع ومدارس الادارة في مختلف المنظمات واساليباها وتطويرها واختشاف مكام الخلل والمشاكل وحلها .\n\nالدكتور بشكل عام :\nالتحضير دائم .\nطريقة الشرح سلايدات عباره عن outline لكل محاضرة ، يبدا الدكتور بالشرح والكلام وذكر الحالات مشاركة تجربته اليابانيه (لدراسته في اليابان)\nومستمع جيد للطلاب ويعطي فرصة للنقاش وكل ما كان الكلاس فيه طلاب يشاركون ويتنقاشون زادت متعته .\n\nالدكتور يكرررف بالكيز ستدي تقريبا كل اسبوع في مادة 450 وفيه هوموركات في 440 ولكن بشكل اخف\n\nالكويزات تقريبا 4 او 5 لكل كورس خلال الترم\n\nفي نهاية الترم يعطي بروجكت\n\nالمياجر والفاينلات :\nبشكل عام ليست سهله ولا صعبه .\nلانه يخلي جزء بسيط خيارات … تقريبا 40% و 60% اسئلة كتابية تتطلب انك تسهب في الشرح والامثله والكتابة .\nوالحقيقة طويلة تاخذ منك تقريبا ساعتين ونصف الى ثلاث ساعات .\n\nملاحظة : زيارتك له بالاوفيس اور بشكل دوري مهم .\nاللي بينزل كورسين معاه بنفس الترم بينضغط .\nبشكل مختصر :\nالتزم بالحضور ، شارك بالمحاضرة، تابع مع الدكتور اول باول . وباذن الله موفق.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1433836-mgt440", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-muhammad-jameel-qazi/98468/12", "user": "hisham.s", "ts": 1447934547000, "tid": 98468, "pn": 12}}]}', 1447934547000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
COMMIT;
